// Preserve the existing CDS warning for a known observation even before a total.
// The composite appearance descriptor is not a diagnosis of shock/dehydration.
const cds=expandedScores.find(score=>score.id==='cds');
const cdsOwnValue=(values,key)=>{
 try{
  if(values===null||typeof values!=='object'||Array.isArray(values))return undefined;
  const descriptor=Object.getOwnPropertyDescriptor(values,key);
  return descriptor&&Object.hasOwn(descriptor,'value')?descriptor.value:undefined;
 }catch{return undefined;}
};
cds.safeValidate=values=>cds.fields.filter(field=>{
 const value=cdsOwnValue(values,field.id);
 return !['number','string'].includes(typeof value)||!field.options.some(option=>String(option.value)===String(value));
}).map(field=>field.id);
cds.assessPartial=values=>[2,'2'].includes(cdsOwnValue(values,'appearance'))?{level:'high',alert:'Sonolência importante, flacidez ou má perfusão exigem avaliação imediata, independentemente da classificação numérica.'}:null;

export function calculateExpanded(score,x){
 let r;
 if(score.compute)r=score.compute(x);
 else {const breakdown=score.fields.map(f=>({label:f.label,points:x[f.id]}));const total=breakdown.reduce((a,b)=>a+b.points,0);const band=score.bands?.find(row=>total<=row[0]);r={total,breakdown,label:band?.[1]||'Pontuação do instrumento',level:band?.[2]||'medium',action:band?.[3]||score.action,audit:breakdown.map(v=>v.points).join(' + ')};}
 const raw=r.total;const scale=10**(score.precision??2);r.total=raw===null?null:(score.id==='duke-treadmill'||score.id==='duke-alexander-1998'||score.id==='duke-mark-1991')?raw:Math.round((raw+Number.EPSILON)*scale)/scale;
 r.alerts=r.alerts||[];
 if(score.id==='phq9'&&x.q8>0)r.alerts.push('Resposta positiva sobre morte/autoagressão: avaliar diretamente ideação, intenção, plano e segurança agora, independentemente do total.');
 if(score.id==='cds'&&x.appearance===2)r.alerts.push('Sonolência importante, flacidez ou má perfusão exigem avaliação imediata, independentemente da classificação numérica.');
 return {complete:true,...r,audit:`${r.audit} = ${score.categorical?r.displayValue:(r.total===null?'NT':r.displayValue??r.total)}`};
}

